pub mod convert;
pub mod service;
pub mod session;

#[allow(clippy::all)] // generated by tonic-build
pub mod proto {
    tonic::include_proto!("traverse.v1");
}

use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;

use tonic::codec::CompressionEncoding;
use tonic::transport::Server;
use tracing::info;

use crate::auth::AuthCatalog;
use crate::registry::DatabaseRegistry;

use self::proto::traverse_service_server::TraverseServiceServer;
use self::service::FgServiceImpl;
use self::session::SessionManager;

const MAX_MESSAGE_SIZE: usize = 128 * 1024 * 1024; // 128 MB

/// gRPC server, sharing the `DatabaseRegistry` with the Bolt and HTTP servers.
pub struct GrpcServer {
    registry: Arc<DatabaseRegistry>,
    addr: SocketAddr,
    auth_catalog: Option<Arc<std::sync::RwLock<AuthCatalog>>>,
}

impl GrpcServer {
    pub fn new(registry: Arc<DatabaseRegistry>, addr: SocketAddr) -> Self {
        Self {
            registry,
            addr,
            auth_catalog: None,
        }
    }

    /// Attaches an auth catalog (shared with the Bolt server).
    pub fn with_auth_catalog(mut self, catalog: Arc<std::sync::RwLock<AuthCatalog>>) -> Self {
        self.auth_catalog = Some(catalog);
        self
    }

    /// Binds the TCP listener without starting the server; returns the listener and its local
    /// address.
    pub async fn bind(&self) -> std::io::Result<(tokio::net::TcpListener, SocketAddr)> {
        let listener = tokio::net::TcpListener::bind(self.addr).await?;
        let local_addr = listener.local_addr()?;
        Ok((listener, local_addr))
    }

    /// Runs on a pre-bound listener (see `bind()`).
    pub async fn run_with_listener(
        self,
        listener: tokio::net::TcpListener,
    ) -> Result<(), tonic::transport::Error> {
        let sessions = Arc::new(SessionManager::new(crate::config::tx_idle_timeout()));
        sessions.spawn_cleanup();

        let svc = FgServiceImpl {
            registry: self.registry,
            sessions,
            auth_catalog: self.auth_catalog,
            verified: Default::default(),
        };

        let incoming = tokio_stream::wrappers::TcpListenerStream::new(listener);
        Server::builder()
            .tcp_nodelay(true)
            .http2_adaptive_window(Some(true))
            .http2_keepalive_interval(Some(Duration::from_secs(10)))
            .http2_keepalive_timeout(Some(Duration::from_secs(20)))
            .add_service(
                TraverseServiceServer::new(svc)
                    .max_decoding_message_size(MAX_MESSAGE_SIZE)
                    .max_encoding_message_size(MAX_MESSAGE_SIZE)
                    .accept_compressed(CompressionEncoding::Gzip)
                    .send_compressed(CompressionEncoding::Gzip),
            )
            .serve_with_incoming(incoming)
            .await
    }

    /// Runs, returning the bound address (tests); stops gracefully on the shutdown signal.
    pub async fn run_until_shutdown(
        self,
        shutdown: tokio::sync::oneshot::Receiver<()>,
    ) -> Result<SocketAddr, tonic::transport::Error> {
        let listener = tokio::net::TcpListener::bind(self.addr).await.unwrap();
        let local_addr = listener.local_addr().unwrap();

        let sessions = Arc::new(SessionManager::new(crate::config::tx_idle_timeout()));
        sessions.spawn_cleanup();

        let svc = FgServiceImpl {
            registry: self.registry,
            sessions,
            auth_catalog: self.auth_catalog,
            verified: Default::default(),
        };

        info!("gRPC server listening on {local_addr}");

        let incoming = tokio_stream::wrappers::TcpListenerStream::new(listener);

        tokio::spawn(async move {
            Server::builder()
                .tcp_nodelay(true)
                .http2_adaptive_window(Some(true))
                .http2_keepalive_interval(Some(Duration::from_secs(10)))
                .http2_keepalive_timeout(Some(Duration::from_secs(20)))
                .add_service(
                    TraverseServiceServer::new(svc)
                        .max_decoding_message_size(MAX_MESSAGE_SIZE)
                        .max_encoding_message_size(MAX_MESSAGE_SIZE)
                        .accept_compressed(CompressionEncoding::Gzip)
                        .send_compressed(CompressionEncoding::Gzip),
                )
                .serve_with_incoming_shutdown(incoming, async {
                    let _ = shutdown.await;
                })
                .await
                .ok();
        });

        Ok(local_addr)
    }
}
